 const bmi=slab(host.body,2.5,3,.75,.07,[2.5,4,-.92],dark,[],.01);bmi.name='DoF9 U2 actual BMI270 LGA14 package';const bmiPads=[];for(const sign of[-1,1]){for(let i=0;i<4;i++)bmiPads.push(mesh(host.body,new THREE.BoxGeometry(.3,.25,.08),metal,[2.5+sign*1.1,4+(i-1.5)*.5,-.96],'DoF9 BMI270 actual seated LGA contact'));for(let i=0;i<3;i++)bmiPads.push(mesh(host.body,new THREE.BoxGeometry(.25,.3,.08),metal,[2.5+(i-1)*.5,4+sign*1.35,-.96],'DoF9 BMI270 actual seated LGA contact'));}
