function fixing(host){const metal=materials.metal(0xaeb7aa,{roughness:.4}),s=new THREE.Shape();s.absarc(0,0,1.6,0,tau,false);const h=new THREE.Path();for(let i=0;i<6;i++){const a=-i*Math.PI/3,x=Math.cos(a)*.67,y=Math.sin(a)*.67;i?h.lineTo(x,y):h.moveTo(x,y);}h.closePath();s.holes.push(h);const head=solid(host.body,s,.5,[0,0,-3.97],metal,'DoF9 actual fixed rear retaining hex head'),floor=mesh(host.body,new THREE.CylinderGeometry(.68,.68,.1,6).rotateX(Math.PI/2),metal,[0,0,-3.42],'DoF9 actual blind hex floor'),shank=mesh(host.body,new THREE.CylinderGeometry(.7,.7,6.5,32).rotateX(Math.PI/2),metal,[0,0,-.22],'DoF9 actual fixed retaining screw shank');return{head,floor,shank};}
